/bin/zsh -lc "git diff -- analysis.py && python -c 'import pandas as pd,numpy as np; from analysis import fit_wealth_quantile; d=pd.read_csv(\"data/nls_incarceration_processed.csv\");
for q in (.1,.5,.9):
 r=fit_wealth_quantile(d,q); b=np.array(list(r[\"coef\"].values())); X=np.column_stack((np.ones(len(d)),d.race.eq(\"black\"),d.race.eq(\"hipanic\"),d.sex.eq(\"male\"),d.ever_jailed)); u=d.composite_wealth_1996.to_numpy()-X@b; loss=np.where(u>=0,q*u,(q-1)*u).sum(); print(q,loss)'"

